<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientPublicAllowVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientPublicAllowAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientPublicAllowAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientPublicAllowAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that isPublicAllow returns null on a freshly created holder.
         */
        public function testPublicAllowNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTrustedClientPublicAllowAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isPublicAllowAssigned());
            $this->assertNull($holder->isPublicAllow());
        }
}
class ImplWithTrustedClientPublicAllowAttributeHolderUnitTest
{
  use TrustedClientPublicAllowAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedPublicAllowRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultPublicAllow();
    }}
